CREATE TABLE public.student_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), message text NOT NULL CHECK (char_length(message) BETWEEN 5 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.student_feedback TO authenticated;
GRANT ALL ON public.student_feedback TO service_role;
ALTER TABLE public.student_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY feedback_owner_read ON public.student_feedback FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY feedback_owner_insert ON public.student_feedback FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE TABLE public.learning_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('voice','classroom','audio')), completed_at timestamptz NOT NULL DEFAULT now(), UNIQUE (id,user_id));
GRANT SELECT, INSERT ON public.learning_sessions TO authenticated;
GRANT ALL ON public.learning_sessions TO service_role;
ALTER TABLE public.learning_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY sessions_owner_read ON public.learning_sessions FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY sessions_owner_insert ON public.learning_sessions FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE TABLE public.ai_access_blocks (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.ai_access_blocks TO authenticated;
GRANT ALL ON public.ai_access_blocks TO service_role;
ALTER TABLE public.ai_access_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY access_blocks_owner_read ON public.ai_access_blocks FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY access_blocks_owner_write ON public.ai_access_blocks FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY access_blocks_owner_update ON public.ai_access_blocks FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE FUNCTION public.eduvault_impact_totals() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT jsonb_build_object('students', (SELECT count(*) FROM public.profiles), 'questions', (SELECT coalesce(sum(total),0) FROM public.quiz_attempts), 'quizzes', (SELECT count(*) FROM public.quiz_attempts), 'sessions', (SELECT count(*) FROM public.learning_sessions) + (SELECT count(*) FROM public.viva_sessions), 'accuracy', (SELECT CASE WHEN sum(total)>0 THEN round(100.0*sum(score)/sum(total),1) ELSE NULL END FROM public.quiz_attempts)); $$;
REVOKE ALL ON FUNCTION public.eduvault_impact_totals() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.eduvault_impact_totals() TO authenticated, service_role;